const express = require('express');
const app = express();

app.get('/boom', (req, res) => {
  // Synchronous throw: Express auto-forwards it to the error handler.
  throw new Error('something failed');
});

app.get('/forward', (req, res, next) => {
  next(new Error('explicitly forwarded'));
});

// 4-arg signature => Express treats this as the error handler.
app.use((err, req, res, next) => {
  console.error(err.stack);
  if (res.headersSent) return next(err);
  res.status(err.status || 500).json({ error: err.message });
});

app.listen(3000);

const express = require('express');
const app = express();
app.use(express.json());

// Reusable wrapper: catches async rejections and calls next(err).
const asyncHandler = (fn) => (req, res, next) =>
  Promise.resolve(fn(req, res, next)).catch(next);

const getUser = async (id) => {
  if (!id) throw Object.assign(new Error('id required'), { status: 400 });
  return { id, name: 'Ada' };
};

app.get('/users/:id', asyncHandler(async (req, res) => {
  const user = await getUser(req.params.id); // rejection -> next(err)
  res.json(user);
}));

app.use((err, req, res, next) => {
  res.status(err.status || 500).json({ error: err.message });
});

app.listen(3000);

