const express = require('express');
const app = express();

app.get('/users/:id', (req, res) => {
  const id = Number(req.params.id);          // params are strings
  if (!Number.isInteger(id)) {
    return res.status(400).json({ error: 'id must be an integer' });
  }
  const page = Number(req.query.page) || 1;  // query values optional
  const sort = typeof req.query.sort === 'string' ? req.query.sort : 'id';
  res.json({ id, page, sort });
});

// Capture the rest of the path under /files (e.g. /files/docs/2024/a.pdf).
// Prefix-mounting + req.path is portable across Express 4 and 5.
app.use('/files', (req, res) => {
  res.json({ filepath: req.path.replace(/^\//, '') }); // 'docs/2024/a.pdf'
});

app.listen(3000);

