const express = require('express');
const path = require('path');
const app = express();

// API routes first so the SPA fallback never shadows them.
app.get('/api/health', (req, res) => res.json({ ok: true }));

// Serve /static/* from ./public with long-lived caching.
app.use(
  '/static',
  express.static(path.join(__dirname, 'public'), {
    maxAge: '1d',
    immutable: true
  })
);

// SPA fallback: any unmatched GET returns index.html for client routing.
// Using app.use here is portable (Express 5 dropped the bare '*' path string;
// you'd otherwise need app.get('/*splat', ...)).
app.use((req, res) => {
  if (req.method !== 'GET') return res.sendStatus(404);
  res.sendFile(path.join(__dirname, 'public', 'index.html'));
});

app.listen(3000);

