const express = require('express');
const jwt = require('jsonwebtoken');
const app = express();
app.use(express.json());

const SECRET = process.env.JWT_SECRET; // never hard-code

app.post('/login', (req, res) => {
  // (validate credentials first in real code)
  const token = jwt.sign({ sub: req.body.userId, role: 'user' }, SECRET, {
    expiresIn: '15m'
  });
  res.json({ token });
});

function authenticate(req, res, next) {
  const header = req.headers.authorization || '';
  const token = header.startsWith('Bearer ') ? header.slice(7) : null;
  if (!token) return res.status(401).json({ error: 'missing token' });
  try {
    req.user = jwt.verify(token, SECRET); // stateless verification
    next();
  } catch {
    res.status(401).json({ error: 'invalid or expired token' });
  }
}

app.get('/me', authenticate, (req, res) => res.json({ user: req.user }));

app.listen(3000);

