const express = require('express');
const { body, validationResult } = require('express-validator');
const app = express();
app.use(express.json());

const validateUser = [
  body('email').isEmail().normalizeEmail(),       // validate + sanitize
  body('name').trim().isLength({ min: 2 }).escape(),
  body('age').optional().isInt({ min: 0 }).toInt(),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    next();
  }
];

app.post('/users', validateUser, (req, res) => {
  // req.body is now validated and sanitized.
  res.status(201).json({ created: req.body });
});

app.listen(3000);

const express = require('express');
const app = express();

app.get('/item/:id',
  (req, res, next) => {
    if (req.query.skip === '1') return next('route'); // skip to next route
    next(); // continue to the next handler in THIS route
  },
  (req, res) => res.send('handled by first route')
);

// Reached only when next('route') was called above.
app.get('/item/:id', (req, res) => res.send('handled by fallback route'));

app.get('/fail', (req, res, next) => {
  next(new Error('boom')); // jump straight to the error handler
});

app.use((err, req, res, next) => {
  res.status(500).json({ error: err.message });
});

app.listen(3000);

const express = require('express');
